'use strict';

/**
 * Normalize a locale-mixed monetary string to a plain numeric string.
 * Handles en-US ("1,234.56") and de-DE ("1.234,56" / "99,90") mixed in the same feed.
 * Rule: when both '.' and ',' are present, the last one is the decimal separator.
 *       when only ',' is present, it's the decimal separator.
 */
function normalizeAmount(raw) {
  // Strip leading/trailing whitespace and optional currency symbol
  let s = raw.trim().replace(/^\$/, '');

  const hasDot = s.includes('.');
  const hasComma = s.includes(',');

  if (hasDot && hasComma) {
    const lastDot = s.lastIndexOf('.');
    const lastComma = s.lastIndexOf(',');
    if (lastComma > lastDot) {
      // de-DE: "1.234,56" — dot is thousands separator, comma is decimal
      s = s.replace(/\./g, '').replace(',', '.');
    } else {
      // en-US: "1,234.56" — comma is thousands separator, dot is decimal
      s = s.replace(/,/g, '');
    }
  } else if (hasComma) {
    // Only comma present — treat as decimal separator ("99,90")
    s = s.replace(',', '.');
  }
  // Only dot, or neither: already a plain numeric string

  return s;
}

function sumAmounts(rows) {
  if (!rows || rows.length === 0) return 0;

  let total = 0;
  for (const row of rows) {
    const raw = row && row.amount;
    if (raw == null || raw === '') continue;

    const normalized = normalizeAmount(String(raw));
    const value = Number(normalized);
    if (!isFinite(value)) continue;

    total += value;
  }

  return Math.round(total * 100) / 100;
}

module.exports = { sumAmounts };

